-- P11/P13: estações por meses, pódio revisado de 2025.
-- PDF e demais séries preservados. Derivações sobre resultados congelados.
WITH anterior AS(SELECT result->'rows'->0->'payload' AS payload FROM estudo.notebook_runs WHERE id=95 AND frozen AND status='ok' AND NOT truncated AND row_count=1),
novos_valores AS(SELECT 'estacoes' AS serie,r->>'estacao' AS categoria,jsonb_build_object('valor',r->'percentual','contagem',r->'total','denominador',r->'denominador')||jsonb_build_object('fonte','Notebook · execução #97 · célula 300 rev1','nota','Meses inteiros; deriva contagens mensais do congelamento 95; população anterior preservada') AS atual
 FROM estudo.notebook_runs n CROSS JOIN LATERAL jsonb_array_elements(n.result->'rows')r
 WHERE n.id=97 AND n.cell_id=300 AND n.cell_version=1 AND n.frozen AND n.status='ok' AND NOT n.truncated AND n.row_count=8 AND (r->>'ano')::integer=2025 UNION ALL SELECT r->>'serie',r->>'categoria',jsonb_build_object('valor',r->>'quantidade','contagem',r->'quantidade')||jsonb_build_object('fonte','Notebook · execução #98 · célula 301 rev1','nota','11 critérios, pesos iguais; RANK com empates; origens congeladas em 95; referência PDF intacta') FROM estudo.notebook_runs n CROSS JOIN LATERAL jsonb_array_elements(n.result->'rows')r WHERE n.id=98 AND n.cell_id=301 AND n.cell_version=1 AND n.frozen AND n.status='ok' AND NOT n.truncated AND n.row_count=280 AND r->>'fonte'='atual' AND r->>'bloco'='medalhas'),
alvos AS(SELECT x AS s FROM jsonb_array_elements('[{"id": "estacoes", "status": "transcrito_do_pdf_nao_recalculado", "filtros": {}, "unidade": "percentual", "valores": [{"valor": 11.9, "rotulo": "Verão"}, {"valor": 25.5, "rotulo": "Outono"}, {"valor": 28.3, "rotulo": "Inverno"}, {"valor": 34.3, "rotulo": "Primavera"}], "ressalva": "Meses inteiros confirmados pelo responsável em 01/10/2026 e descritos nas notas insights_previa do DBA: verão dez–fev, outono mar–mai, inverno jun–ago, primavera set–nov. Agrupa os meses dentro do ano civil, não uma estação contínua entre dois anos. Percentual das participações do recorte, calculado pelas contagens mensais congeladas, sem somar percentuais arredondados nem recoletar resultados. Regra revisada: os percentuais históricos do PDF não correspondem a esse agrupamento; referência preservada. Célula 300 rev1, execução 97; origens 95/2025 e 96/2026. Universo anual de 5.279.415 participações, igual aos meses desta edição; não substitui a coleta mais nova de idades.", "pagina_pdf": 11, "casas_decimais": 1}, {"id": "maratonas_medalhas_ouro", "status": "transcrito_pdf", "filtros": {}, "unidade": "texto_publicado", "valores": [{"valor": "1", "rotulo": "Maratona do Rio"}, {"valor": "3", "rotulo": "Maratona de Porto Alegre"}, {"valor": "—", "rotulo": "SP City Marathon"}, {"valor": "—", "rotulo": "Maratona de Floripa"}, {"valor": "—", "rotulo": "Maratona de São Paulo"}, {"valor": "—", "rotulo": "Maratona de Curitiba"}, {"valor": "—", "rotulo": "Maratona Monumental de Brasília"}, {"valor": "7", "rotulo": "New Balance 42k Porto Alegre"}, {"valor": "—", "rotulo": "Maratona de Aracaju"}, {"valor": "—", "rotulo": "Maratona de Salvador"}], "ressalva": "Pódio revisado v1, derivado dos valores congelados em 95, sem nova coleta. 11 critérios com peso igual: maiores quantidades sub4/sub3/sub2h30; menores tempos mínimo/médio/mediano e médias Top10/Top100/melhores5%/10%/50%. Não pontua percentuais. Ouro/prata/bronze para posições 1/2/3 em cada critério; empates compartilham a posição e pulam a seguinte (1,1,3). Usa tempos publicados arredondados ao segundo. Mesmas dez maratonas e populações revisadas em 41 e 67. Zero significa nenhuma medalha atribuída; traços históricos permanecem. A regra é uma inferência dos destaques do PDF, não confirmação do código original. No PDF, o bronze Top5% está em Curitiba (03:16:17), embora Floripa tenha tempo menor (03:14:23). Pelos números históricos, Floripa teria 7 bronzes e Curitiba 1; o quadro mostra 6 e 2. Esse desvio é explicado, sem reescrever o PDF. Célula 301 rev1, execução 98; testes 35 casos em 99. Não compara o mercado nem certifica a qualidade dos resultados.", "pagina_pdf": 13, "casas_decimais": null}, {"id": "maratonas_medalhas_prata", "status": "transcrito_pdf", "filtros": {}, "unidade": "texto_publicado", "valores": [{"valor": "2", "rotulo": "Maratona do Rio"}, {"valor": "7", "rotulo": "Maratona de Porto Alegre"}, {"valor": "—", "rotulo": "SP City Marathon"}, {"valor": "—", "rotulo": "Maratona de Floripa"}, {"valor": "1", "rotulo": "Maratona de São Paulo"}, {"valor": "1", "rotulo": "Maratona de Curitiba"}, {"valor": "—", "rotulo": "Maratona Monumental de Brasília"}, {"valor": "—", "rotulo": "New Balance 42k Porto Alegre"}, {"valor": "—", "rotulo": "Maratona de Aracaju"}, {"valor": "—", "rotulo": "Maratona de Salvador"}], "ressalva": "Pódio revisado v1, derivado dos valores congelados em 95, sem nova coleta. 11 critérios com peso igual: maiores quantidades sub4/sub3/sub2h30; menores tempos mínimo/médio/mediano e médias Top10/Top100/melhores5%/10%/50%. Não pontua percentuais. Ouro/prata/bronze para posições 1/2/3 em cada critério; empates compartilham a posição e pulam a seguinte (1,1,3). Usa tempos publicados arredondados ao segundo. Mesmas dez maratonas e populações revisadas em 41 e 67. Zero significa nenhuma medalha atribuída; traços históricos permanecem. A regra é uma inferência dos destaques do PDF, não confirmação do código original. No PDF, o bronze Top5% está em Curitiba (03:16:17), embora Floripa tenha tempo menor (03:14:23). Pelos números históricos, Floripa teria 7 bronzes e Curitiba 1; o quadro mostra 6 e 2. Esse desvio é explicado, sem reescrever o PDF. Célula 301 rev1, execução 98; testes 35 casos em 99. Não compara o mercado nem certifica a qualidade dos resultados.", "pagina_pdf": 13, "casas_decimais": null}, {"id": "maratonas_medalhas_bronze", "status": "transcrito_pdf", "filtros": {}, "unidade": "texto_publicado", "valores": [{"valor": "3", "rotulo": "Maratona do Rio"}, {"valor": "—", "rotulo": "Maratona de Porto Alegre"}, {"valor": "—", "rotulo": "SP City Marathon"}, {"valor": "6", "rotulo": "Maratona de Floripa"}, {"valor": "—", "rotulo": "Maratona de São Paulo"}, {"valor": "2", "rotulo": "Maratona de Curitiba"}, {"valor": "—", "rotulo": "Maratona Monumental de Brasília"}, {"valor": "—", "rotulo": "New Balance 42k Porto Alegre"}, {"valor": "—", "rotulo": "Maratona de Aracaju"}, {"valor": "—", "rotulo": "Maratona de Salvador"}], "ressalva": "Pódio revisado v1, derivado dos valores congelados em 95, sem nova coleta. 11 critérios com peso igual: maiores quantidades sub4/sub3/sub2h30; menores tempos mínimo/médio/mediano e médias Top10/Top100/melhores5%/10%/50%. Não pontua percentuais. Ouro/prata/bronze para posições 1/2/3 em cada critério; empates compartilham a posição e pulam a seguinte (1,1,3). Usa tempos publicados arredondados ao segundo. Mesmas dez maratonas e populações revisadas em 41 e 67. Zero significa nenhuma medalha atribuída; traços históricos permanecem. A regra é uma inferência dos destaques do PDF, não confirmação do código original. No PDF, o bronze Top5% está em Curitiba (03:16:17), embora Floripa tenha tempo menor (03:14:23). Pelos números históricos, Floripa teria 7 bronzes e Curitiba 1; o quadro mostra 6 e 2. Esse desvio é explicado, sem reescrever o PDF. Célula 301 rev1, execução 98; testes 35 casos em 99. Não compara o mercado nem certifica a qualidade dos resultados.", "pagina_pdf": 13, "casas_decimais": null}]'::jsonb)x),
originais AS(SELECT x AS s,row_number() OVER() AS ord FROM anterior CROSS JOIN LATERAL jsonb_array_elements(payload->'series')x),
series AS(SELECT coalesce(a.s,p.s) AS s,p.ord FROM originais p LEFT JOIN alvos a ON a.s->>'id'=p.s->>'id'
 UNION ALL SELECT a.s,1000+row_number() OVER(ORDER BY a.s->>'id') FROM alvos a WHERE NOT EXISTS(SELECT 1 FROM originais p WHERE p.s->>'id'=a.s->>'id')),
comparacoes AS(SELECT x AS item FROM anterior CROSS JOIN LATERAL jsonb_array_elements(payload->'comparacoes')x WHERE x->>'serie' NOT IN(SELECT jsonb_array_elements_text('["estacoes", "maratonas_medalhas_ouro", "maratonas_medalhas_prata", "maratonas_medalhas_bronze"]'::jsonb))
 UNION ALL SELECT jsonb_build_object('serie',serie,'categoria',categoria,'status','notebook_em_conciliacao','atual',atual) FROM novos_valores)
SELECT payload||jsonb_build_object('meta',payload->'meta'||jsonb_build_object('contrato_versao',5, 'notebook_fontes',(payload->'meta'->'notebook_fontes')||(SELECT jsonb_agg(jsonb_build_object('execucao',id,'celula',cell_id,'revisao',cell_version,'coletado_em',started_at) ORDER BY id) FROM estudo.notebook_runs WHERE id IN(97,98))),
 'series',(SELECT jsonb_agg(s ORDER BY ord) FROM series),
 'comparacoes',(SELECT jsonb_agg(item ORDER BY item->>'serie',item->>'categoria') FROM comparacoes),
 'conciliacao','{"divergente": 0, "nao_recalculado": 0, "compativel_no_valor": 0, "notebook_em_conciliacao": 0, "compativel_no_arredondamento": 0}'::jsonb||(SELECT jsonb_object_agg(status,n) FROM(SELECT item->>'status' AS status,count(*) AS n FROM comparacoes GROUP BY 1)t)) AS payload
 FROM anterior WHERE (SELECT count(*) FROM novos_valores)=34
 AND (SELECT count(DISTINCT serie||'/'||categoria) FROM novos_valores)=34;
